/* Pixel Counter styles */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --btn: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 32px 24px;
  border-radius: 12px;
  box-shadow: 0 0 0 4px var(--accent), 0 8px 24px rgba(0,0,0,0.5);
  text-align: center;
  width: 100%;
  max-width: 400px;
}

h1 {
  color: var(--text);
  font-size: 1.5rem;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.count {
  display: block;
  font-size: 4rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 32px;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  word-break: break-all;
}

.buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 600;
  padding: 12px 24px;
  min-width: 64px;
  border: none;
  border-radius: 8px;
  background: var(--btn);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.1s, background 0.2s, box-shadow 0.2s;
  box-shadow: 0 4px 0 #071a2e;
}

button:hover {
  background: #1a4a7a;
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 #071a2e;
}

#increase, #decrease {
  font-size: 1.75rem;
  padding: 8px 24px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .count {
    font-size: 3rem;
  }
  button {
    font-size: 1.1rem;
    padding: 10px 18px;
  }
  #increase, #decrease {
    font-size: 1.5rem;
    padding: 8px 18px;
  }
}

// Pixel Counter logic
(function () {
  'use strict';

  let count = 0;
  const countEl = document.getElementById('count');
  const increaseBtn = document.getElementById('increase');
  const decreaseBtn = document.getElementById('decrease');
  const resetBtn = document.getElementById('reset');

  function updateDisplay() {
    countEl.textContent = count;
  }

  increaseBtn.addEventListener('click', function () {
    count += 1;
    updateDisplay();
  });

  decreaseBtn.addEventListener('click', function () {
    count -= 1;
    updateDisplay();
  });

  resetBtn.addEventListener('click', function () {
    count = 0;
    updateDisplay();
  });

  updateDisplay();
})();
